from normalizer import FeatureNormalizer

def test_standard_scaling_range():
    fn = FeatureNormalizer()
    res = fn.normalize([10.0, 20.0, 30.0])
    # Invariant: unit range [0.0, 1.0], NOT percentage 0-100
    assert res == [0.0, 0.5, 1.0]

def test_constant_array_zero_division():
    fn = FeatureNormalizer()
    res = fn.normalize([5.0, 5.0, 5.0])
    # Constant series must return all 0.0 without ZeroDivisionError or epsilon artifacts
    assert res == [0.0, 0.0, 0.0]

