from typing import List
from transform import scale_value

class FeatureNormalizer:
    def normalize(self, values: List[float]) -> List[float]:
        if not values:
            return []
        min_v = min(values)
        max_v = max(values)
        if min_v == max_v:
            return [0.0] * len(values)
        return [round(scale_value(v, min_v, max_v), 4) for v in values]
